

# HAPMAP PROJECT: PCA WITH STRICT LD PRUNING i will be good i swear

# 1. Load the required library
library(ggplot2)

# 2. Read PCA results generated by PLINK2
pca <- read.table(
  "hapmap_pca_strict.eigenvec",
  header = TRUE,
  comment.char = "",
  check.names = FALSE
)

# Rename individual identifier columns
names(pca)[1:2] <- c("FID", "IID")

# Inspect the PCA dataset
cat("Number of individuals in PCA:", nrow(pca), "\n")
print(head(pca, 3))

# 3. Read population metadata
pop <- read.table(
  "../data/pop.phe",
  header = FALSE
)

names(pop) <- c("FID", "IID", "Population")

# Convert numeric population codes into labels
pop$Population <- factor(
  pop$Population,
  levels = c(1, 2),
  labels = c("HCB", "JPT")
)

# 4. Merge PCA coordinates with population metadata
pca_data <- merge(
  pca,
  pop,
  by = c("FID", "IID")
)

# Validate sample matching and population counts
stopifnot(
  nrow(pca) == 89,
  nrow(pca_data) == 89,
  !anyNA(pca_data$Population),
  sum(pca_data$Population == "HCB") == 45,
  sum(pca_data$Population == "JPT") == 44
)

cat("\nPopulation distribution:\n")
print(table(pca_data$Population))

# Compare mean PC1 scores between populations
mean_pc1 <- aggregate(
  PC1 ~ Population,
  data = pca_data,
  FUN = mean
)

print(mean_pc1)

# 5. Create the PCA scatter plot
pca_plot <- ggplot(
  pca_data,
  aes(
    x = PC1,
    y = PC2,
    color = Population
  )
) +
  geom_point(size = 3, alpha = 0.8) +
  scale_color_manual(
    values = c("HCB" = "#2878B5", "JPT" = "#E28C32")
  ) +
  labs(
    title = "Population Genetic Structure: HCB vs JPT",
    subtitle = "89 individuals | 22,830 SNPs | LD r² threshold = 0.1",
    x = "PC1",
    y = "PC2",
    color = "Population"
  ) +
  theme_minimal(base_size = 13)

# 6. Save the strict PCA plot
ggsave(
  filename = "pca_HCB_JPT_strict.png",
  plot = pca_plot,
  width = 8,
  height = 5,
  dpi = 300,
  bg = "white"
)

cat("\nStrict PCA plot saved successfully!\n")
